// Labrador torso: loft through barrel cross-sections along the body (local z = world -y),
// closed by apex points at the buttock and the prosternum. Spline seam under the belly.
// Broad, square hindquarters; a soft flank fold toward the stifle (no notch in front of the thigh).
const N = 20;
const sec = (zt, zb, w, keel, zw) => {
  const pts = [];
  for (let i = 0; i < N; i++) {
    const a = -Math.PI / 2 + (i / N) * 2 * Math.PI, c = Math.cos(a), s = Math.sin(a);
    const up = s >= 0;
    const h = up ? (zt - zw) : (zw - zb);
    let x = w * Math.sign(c) * Math.abs(c) ** 0.82;
    if (!up) x *= 1 - keel * Math.abs(s) ** 1.6;      // keel-shaped underside
    else x *= 1 - 0.18 * Math.abs(s) ** 2.5;           // slightly narrower over the spine
    const z = zw + h * Math.sign(s) * Math.abs(s) ** (up ? 0.9 : 0.85);
    pts.push([x, z]);
  }
  return pts;
};
const S = [
  // y,    zt,  zb,  w,   keel, zw
  [ 318, 515, 400,  84, 0.30, 460],
  [ 285, 537, 360, 114, 0.40, 452],   // buttocks
  [ 225, 548, 350, 120, 0.42, 446],   // hips / croup, over the thighs
  [ 155, 554, 358, 112, 0.42, 450],   // flank, soft fold to the stifle
  [  80, 557, 338, 114, 0.48, 448],   // loin
  [   0, 560, 305, 126, 0.45, 440],   // back ribs
  [ -80, 564, 288, 130, 0.45, 435],   // widest barrel
  [-160, 572, 284, 126, 0.50, 440],   // withers
  [-222, 566, 290, 118, 0.50, 445],   // shoulders
  [-268, 530, 305, 104, 0.45, 440],
  [-296, 482, 345,  78, 0.40, 425],   // point of shoulder / prosternum
];
const sketches = S.map(([y, zt, zb, w, k, zw]) => {
  const p = sec(zt, zb, w, k, zw);
  return drawPointsInterpolation([...p, p[0]]).sketchOnPlane('XY', -y);
});
const body = sketches[0].loftWith(sketches.slice(1), {
  ruled: false,
  startPoint: [0, 462, -336],   // buttock apex (world y = +336)
  endPoint: [0, 418, 318],      // prosternum apex (world y = -318)
});
// local (x, ly, lz) -> world (x, -lz, ly)
return body.rotate(90, [0, 0, 0], [1, 0, 0]);

// Neck: thick and muscular, deep fore-aft; the crest starts well back on the withers and the
// throat runs full into the jaw. Teardrop sections (broad crest, narrower throat). Ends buried.
const N = 20;
const sec = (cy, ru, rvBack, rvFront) => Array.from({ length: N }, (_, i) => {
  const a = Math.PI / 2 + (i / N) * 2 * Math.PI, c = Math.cos(a), s = Math.sin(a);
  const rv = s < 0 ? rvFront : rvBack;               // s<0 = throat side (-y)
  let x = ru * Math.sign(c) * Math.abs(c) ** 0.85;
  if (s < 0) x *= 1 - 0.30 * (-s) ** 2;              // throat narrower than the crest
  return [x, cy + rv * Math.sign(s) * Math.abs(s) ** 0.9];
});
const S = [
  // z,   cy,   ru, back, front
  [400, -215, 84,  85, 75],    // buried in the chest
  [450, -230, 86,  95, 85],
  [500, -250, 80, 100, 90],    // base of the neck, crest flowing into the withers
  [560, -280, 72,  92, 88],
  [610, -305, 66,  78, 80],
  [650, -322, 60,  62, 66],
  [690, -330, 54,  46, 50],    // inside the back of the skull
];
const sk = S.map(([z, cy, ru, b, f]) => {
  const p = sec(cy, ru, b, f);
  return drawPointsInterpolation([...p, p[0]]).sketchOnPlane('XY', z);
});
const neck = sk[0].loftWith(sk.slice(1), { ruled: false });
// boolean with a generous box rebuilds a clean, outward-facing solid (end caps buried)
return neck.intersect(makeBox([-150, -450, 400], [150, -100, 700]));

// Labrador head, level, nose to -y: broad flat skull, full cheeks, clear stop, then a short, deep,
// squarish muzzle (~105 mm, stop at y -422 to nose at ~-530) closing in a blunt rounded nose.
// Loft through cross-sections (local z = world -y).
const N = 20;
const sec = (zt, zb, w, zw, topFlat, flews, sq) => Array.from({ length: N }, (_, i) => {
  const a = -Math.PI / 2 + (i / N) * 2 * Math.PI, c = Math.cos(a), s = Math.sin(a);
  const up = s >= 0;
  let x = w * Math.sign(c) * Math.abs(c) ** sq;          // sq < 0.8 = squarer section
  if (up) x *= 1 - topFlat * Math.abs(s) ** 3;           // skull top: broad, flat
  else x *= 1 - (0.35 - flews) * Math.abs(s) ** 1.5;     // underjaw narrows; flews keep it full
  const h = up ? zt - zw : zw - zb;
  const z = zw + h * Math.sign(s) * Math.abs(s) ** (up ? 0.7 : 0.8);
  return [x, z];
});
const S = [
  // y,    zt,  zb,  w,  zw, topFlat, flews, sq
  [-292, 700, 615, 60, 660, 0.30, 0.00, 0.80],   // back of the skull, inside the neck
  [-312, 714, 594, 73, 656, 0.30, 0.00, 0.80],   // occiput
  [-342, 721, 585, 80, 653, 0.28, 0.05, 0.80],   // cheeks, ear set
  [-375, 723, 584, 81, 650, 0.26, 0.06, 0.80],   // broad skull
  [-402, 716, 587, 74, 648, 0.25, 0.10, 0.78],   // brows
  [-422, 700, 590, 63, 645, 0.20, 0.14, 0.74],   // stop
  [-440, 689, 590, 56, 642, 0.15, 0.18, 0.70],   // muzzle root
  [-466, 684, 592, 53, 641, 0.15, 0.20, 0.68],   // deep, square muzzle
  [-490, 680, 595, 50, 641, 0.15, 0.20, 0.68],
  [-506, 676, 600, 46, 641, 0.18, 0.16, 0.70],   // nose and flews
  [-518, 670, 609, 38, 641, 0.18, 0.12, 0.76],   // blunt front, rounding off
  [-526, 662, 620, 25, 641, 0.15, 0.10, 0.85],
];
const sk = S.map(([y, zt, zb, w, zw, t, f, q]) => {
  const p = sec(zt, zb, w, zw, t, f, q);
  return drawPointsInterpolation([...p, p[0]]).sketchOnPlane('XY', -y);
});
const head = sk[0].loftWith(sk.slice(1), {
  ruled: false,
  startPoint: [0, 660, 276],    // world y = -276
  endPoint: [0, 641, 531],      // nose leather
});
return head.rotate(90, [0, 0, 0], [1, 0, 0]);

// Left foreleg (x>0): straight vertical column, strong bone tapering from the elbow to the pastern,
// elbow point standing out behind, compact round paw with a flat sole. Above the elbow it slides in
// under the chest wall. Horizontal-section loft.
const N = 16;
const ell = (cx, cy, ru, rv, front = 1.0, back = 1.0) => Array.from({ length: N }, (_, i) => {
  const a = Math.PI / 2 + (i / N) * 2 * Math.PI, c = Math.cos(a), s = Math.sin(a);
  const r = s < 0 ? rv * front : rv * back;          // s<0 = toward -y (toes)
  return [cx + ru * Math.sign(c) * Math.abs(c) ** 0.85, cy + r * Math.sign(s) * Math.abs(s) ** 0.85];
});
const S = [
  // z,  cx,  cy,   ru, rv, front, back
  [  8, 78, -236, 32, 35, 1.05, 1.0],   // paw sole
  [ 22, 78, -236, 34, 39, 1.05, 1.0],   // toes
  [ 38, 78, -232, 30, 33, 1.03, 1.0],   // knuckles
  [ 58, 77, -229, 26, 28, 1.0, 1.0],    // pastern
  [ 90, 77, -228, 26, 29, 1.0, 1.0],
  [120, 77, -228, 29, 33, 1.0, 1.0],    // carpus (wrist)
  [170, 77, -227, 30, 35, 1.0, 1.0],
  [220, 77, -225, 32, 38, 1.0, 1.0],    // forearm
  [262, 77, -221, 35, 42, 1.0, 1.08],
  [298, 76, -217, 36, 46, 1.0, 1.15],   // elbow point behind
  [340, 72, -224, 33, 45, 1.0, 1.0],    // upper arm, sliding under the chest wall
  [400, 62, -232, 28, 40, 1.0, 1.0],
];
const sk = S.map(([z, cx, cy, ru, rv, f, b]) => {
  const p = ell(cx, cy, ru, rv, f, b);
  return drawPointsInterpolation([...p, p[0]]).sketchOnPlane('XY', z);
});
const leg = sk[0].loftWith(sk.slice(1), { ruled: false, startPoint: [78, -237, 0.5], endPoint: [56, -234, 430] });
return leg.intersect(makeBox([0, -400, 0], [200, -100, 500]));   // flat sole on the floor

