// sweeping forward to a well-angled stifle, broad thigh whose top runs inward under the croup.
// Horizontal-section loft.
const N = 16;
const ell = (cx, cy, ru, rv, front = 1.0) => Array.from({ length: N }, (_, i) => {
  const a = Math.PI / 2 + (i / N) * 2 * Math.PI, c = Math.cos(a), s = Math.sin(a);
  const r = s < 0 ? rv * front : rv;
  return [cx + ru * Math.sign(c) * Math.abs(c) ** 0.85, cy + r * Math.sign(s) * Math.abs(s) ** 0.85];
});
const S = [
  // z,  cx,  cy,  ru,  rv, front
  [  8, 80, 294, 32, 36, 1.06],   // paw sole
  [ 22, 80, 294, 34, 40, 1.06],   // toes
  [ 40, 80, 299, 30, 34, 1.03],
  [ 62, 80, 307, 26, 28, 1.0],    // rear pastern (metatarsus)
  [105, 80, 310, 26, 28, 1.0],
  [150, 80, 308, 27, 31, 1.0],    // hock (smooth)
  [200, 82, 292, 31, 43, 1.0],    // gaskin
  [250, 84, 268, 36, 60, 1.0],
  [300, 85, 248, 41, 82, 1.0],    // stifle front at y~166
  [350, 85, 240, 44, 94, 1.0],
  [410, 83, 239, 44, 98, 1.0],    // thigh
  [460, 76, 244, 40, 86, 1.0],
  [500, 64, 250, 34, 62, 1.0],    // inside the croup
