const sk = S.map(([z, cx, cy, ru, rv, f]) => {
  const p = ell(cx, cy, ru, rv, f);
  return drawPointsInterpolation([...p, p[0]]).sketchOnPlane('XY', z);
});
const leg = sk[0].loftWith(sk.slice(1), { ruled: false, startPoint: [80, 294, 0.5], endPoint: [58, 252, 520] });
return leg.intersect(makeBox([0, 100, 0], [200, 420, 560]));   // flat sole on the floor

// Otter tail: very thick at the root, round and full along its length, a blunt rounded tip;
// relaxed straight back and ~28 deg down. Local +z from the root (rx -118).
const N = 14;
const circ = (r) => Array.from({ length: N }, (_, i) => {
  const a = (i / N) * 2 * Math.PI;
  return [r * Math.cos(a), r * Math.sin(a)];
});
const S = [
  // local z, r
  [  0, 35],    // root, buried in the croup
  [ 60, 33],
  [140, 30],
  [220, 26],
  [290, 22],
  [340, 18],
  [368, 14],
  [382,  9],
];
const sk = S.map(([z, r]) => {
  const p = circ(r);
  return drawPointsInterpolation([...p, p[0]]).sketchOnPlane('XY', z);
});
return sk[0].loftWith(sk.slice(1), { ruled: false, startPoint: [0, 0, -20], endPoint: [0, 0, 388] });

// Left drop ear: leaf-shaped flap (side outline) folded over at the set onto the skull, its inner
// face lying against the cheek (front band), edges rounded.
const outline = (pts) => drawPointsInterpolation([...pts, pts[0]]);
const side = [   // (y, z): set at the back of the skull, rounded tip low and slightly forward
  [-368, 712], [-345, 718], [-320, 713], [-308, 697], [-310, 670], [-320, 642],
  [-335, 616], [-350, 600], [-363, 597], [-373, 610], [-379, 640], [-381, 672], [-377, 697],
];
const front = [  // (x, z): fold over the skull at the top, flap lying on the cheek
  [56, 718], [74, 722], [88, 712], [95, 691], [97, 662], [94, 632], [88, 607], [80, 592],
  [68, 596], [71, 613], [74, 636], [76, 662], [75, 685], [68, 702], [56, 709],
];
let b = outline(side).sketchOnPlane('YZ', 40).extrude(70);              // x in [40, 110]
b = b.intersect(outline(front).sketchOnPlane('XZ', 280).extrude(130));   // y in [-410, -280]
try { return b.fillet(2.5); } catch (e) { return b; }

